#!/usr/bin/env python3
from __future__ import annotations
import argparse, base64, hashlib, json, py_compile, shutil
from datetime import datetime
from pathlib import Path
FILES = {
  "configs/polarimetric_representation_benchmark_v1.yaml": "",
  "datasets/polarimetric_detection_dataset_v1.py": "",
  "features/__init__.py": "IiIiRmVhdHVyZSBleHRyYWN0aW9uIG1vZHVsZXMgZm9yIGJhbGxvb24gcmFkYXIgZXhwZXJpbWVudHMuIiIiCg==",
  "features/polarimetric_rd.py": "",
  "models/polarimetric_representation_fcn.py": "",
  "scripts/run_polarimetric_representation_benchmark_v1.py": "",
  "scripts/summarize_polarimetric_representation_benchmark_v1.py": "",
  "scripts/test_polarimetric_representation_pipeline_v1.py": "",
  "training/train_polarimetric_representation_fcn.py": ""
}
HASHES = {
  "configs/polarimetric_representation_benchmark_v1.yaml": "bb759813de8108c7c7da6fdefd33011a6f7e3dc47ae3336e44186335cc1ad6ec",
  "datasets/polarimetric_detection_dataset_v1.py": "e2f90a185ac6cbae62dc5e944f0c94357a528ac71ed38aae7da6f022dbc2d1e6",
  "features/__init__.py": "4bd33f0a1f7b49e2049be10d57cacec623b49bdd9b1ccee9a7ff8ce3978181bb",
  "features/polarimetric_rd.py": "2b1dbc92aa10882295df9186d92309d50ce7971d424c9f2d9732b73702b3f416",
  "models/polarimetric_representation_fcn.py": "4149d44a1196fe6e58b2de31329fd1aa712076ec8b34b082d662f17f969eca4b",
  "scripts/run_polarimetric_representation_benchmark_v1.py": "3652cc87dab9c7ca9cb6dd8826e853c133a265aee7abcde8860d8189aa38bf86",
  "scripts/summarize_polarimetric_representation_benchmark_v1.py": "a1b891e56caa993b0740cf2d8dc36ec57eaddbcd1380579424f10813fcd86ff1",
  "scripts/test_polarimetric_representation_pipeline_v1.py": "6d7b2d1d71a51e911e16da7b15c0747e085c8320672d00ffb3f3ef47fffcc073",
  "training/train_polarimetric_representation_fcn.py": "2df72f17d6079635c794d826fe60d1aaf7d575c8051ee05aa9d590bf1743589c"
}
REQUIRED = ("scripts/train_detection_baseline_v2.py", "datasets/detection_dataset_v2.py", "models/simple_fcn.py")
def sha256(data: bytes) -> str: return hashlib.sha256(data).hexdigest()
def main() -> None:
    parser=argparse.ArgumentParser(description="Install explicit polarimetric representation benchmark v1")
    parser.add_argument("--dry-run", action="store_true")
    args=parser.parse_args(); project_root=Path(__file__).resolve().parent
    missing=[x for x in REQUIRED if not (project_root/x).is_file()]
    if missing:
        print("[错误] 请把安装脚本直接放在 balloon_radar_project 项目根目录。")
        for x in missing: print("  - 缺少", x)
        raise SystemExit(2)
    stamp=datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_root=project_root/"backups"/f"polarimetric_representation_benchmark_v1_{stamp}"
    installed=[]; skipped=[]; backed=[]
    for rel, encoded in FILES.items():
        content=base64.b64decode(encoded)
        if sha256(content)!=HASHES[rel]: raise RuntimeError(f"内置哈希校验失败: {rel}")
        target=project_root/rel
        if target.is_file() and sha256(target.read_bytes())==HASHES[rel]:
            skipped.append(rel); print("[跳过] 已是目标版本:", rel); continue
        if args.dry_run:
            print("[预览] 将写入:", rel); continue
        if target.exists():
            backup=backup_root/rel; backup.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(target, backup); backed.append(rel); print("[备份]", rel)
        target.parent.mkdir(parents=True, exist_ok=True); target.write_bytes(content)
        installed.append(rel); print("[写入]", rel)
    if args.dry_run: return
    for rel in FILES:
        if rel.endswith('.py'):
            py_compile.compile(str(project_root/rel), doraise=True); print("[语法通过]", rel)
    record_dir=project_root/"results/data_audit/polarimetric_representation_benchmark_v1"; record_dir.mkdir(parents=True, exist_ok=True)
    record={"installed_at":datetime.now().isoformat(),"project_root":str(project_root),"installed_files":installed,"skipped_identical_files":skipped,"backed_up_files":backed,"backup_root":str(backup_root) if backed else None,"hashes":HASHES}
    (record_dir/"install_record.json").write_text(json.dumps(record,ensure_ascii=False,indent=2),encoding="utf-8")
    print("\n"+"="*88)
    print("安装完成：显式极化表征基准 Stage 2")
    print("第一步：python scripts/test_polarimetric_representation_pipeline_v1.py")
    print("第二步：python scripts/run_polarimetric_representation_benchmark_v1.py --folds 1 4 --modes power2 ri4 polar6 ri8 --smoke")
    print("="*88)
if __name__ == "__main__": main()
